function build(M) {
  const W = 1.6, H = 0.8;
  const parts = [];
  parts.push(M.box(W, H, W, 0));
  for (let i = 1; i < 8; i++) {
    const y = i * H / 8;
    parts.push(M.box(W + 0.02, 0.03, W + 0.02, y - 0.015));
  }
  for (let i = -3; i <= 3; i++) {
    const p = i * W / 7;
    parts.push(M.box(0.03, H, W + 0.03, 0, p));
    parts.push(M.T(M.box(0.03, H, W + 0.03, 0), {ry: 90, pos: [0, 0, p]}));
  }
  const wicker = M.merge(parts);
  const floor = M.box(W + 0.04, 0.06, W + 0.04, -0.04);
  const rimParts = [];
  const r = 0.06, h = W / 2;
  rimParts.push(M.pipe([-h, H, -h], [h, H, -h], r, 16));
  rimParts.push(M.pipe([h, H, -h], [h, H, h], r, 16));
  rimParts.push(M.pipe([h, H, h], [-h, H, h], r, 16));
  rimParts.push(M.pipe([-h, H, h], [-h, H, -h], r, 16));
  for (const [x, z] of [[-h, -h], [h, -h], [h, h], [-h, h]]) {
    rimParts.push(M.T(M.sphere(r, 16, 10), {pos: [x, H, z]}));
  }
  const rim = M.merge(rimParts);
  const poles = [];
  const ph = 0.72;
  for (const [x, z] of [[-ph, -ph], [ph, -ph], [ph, ph], [-ph, ph]]) {
    poles.push(M.pipe([x, H, z], [x, 1.16, z], 0.025, 12));
    poles.push(M.T(M.cyl(0.04, 0.04, 12, 0), {pos: [x, 1.16, z]}));
  }
  const ropes = [];
  for (const s of [-1, 1]) {
    ropes.push(M.T(M.torus(0.1, 0.02, 20, 8), {rx: 90, pos: [0, 0.5, s * (h + 0.03)]}));
    ropes.push(M.T(M.torus(0.1, 0.02, 20, 8), {rz: 90, pos: [s * (h + 0.03), 0.5, 0]}));
  }
  return [
    {material: "orange", look: "solid", mesh: wicker},
    {material: "dark_steel", look: "solid", mesh: floor},
    {material: "copper", look: "solid", mesh: rim},
    {material: "steel", look: "solid", mesh: M.merge(poles)},
    {material: "white", look: "solid", mesh: M.merge(ropes)}
  ];
}

function build(M) {
  const steel = [], gold = [], dark = [], red = [];
  const r = 0.09;
  [-0.1, 0.1].forEach(x => {
    const body = M.lathe([[0,0],[r,0],[r,0.62],[r*0.85,0.68],[r*0.5,0.72],[0.025,0.73],[0,0.73]], 32);
    steel.push(M.T(body, {pos: [x, 0, 0]}));
    dark.push(M.T(M.torus(r, 0.008, 32, 8), {pos: [x, 0.02, 0]}));
    dark.push(M.T(M.torus(r, 0.006, 32, 8), {pos: [x, 0.6, 0]}));
    gold.push(M.T(M.cyl(0.02, 0.06, 16, 0.73), {pos: [x, 0, 0]}));
    gold.push(M.T(M.cyl(0.035, 0.012, 16, 0.79), {pos: [x, 0, 0]}));
    gold.push(M.pipe([x, 0.77, 0], [x + 0.04, 0.77, 0], 0.01, 12));
    steel.push(M.T(M.cyl(0.022, 0.01, 20, 0), {pos: [x + 0.05, 0.77, 0], rz: 90}));
    red.push(M.T(M.cyl(0.018, 0.004, 20, 0), {pos: [x + 0.061, 0.77, 0], rz: 90}));
    dark.push(M.pipe([x, 0.8, 0], [x * 0.6, 0.86, 0], 0.012, 10));
    dark.push(M.pipe([x * 0.6, 0.86, 0], [0, 0.9, 0], 0.012, 10));
  });
  return [
    {material: "steel", look: "solid", mesh: M.merge(steel)},
    {material: "gold", look: "solid", mesh: M.merge(gold)},
    {material: "dark_steel", look: "solid", mesh: M.merge(dark)},
    {material: "red", look: "solid", mesh: M.merge(red)}
  ];
}

function build(M) {
  const frame = [];
  frame.push(M.T(M.torus(0.5, 0.025, 40, 8), {pos: [0, 0.02, 0]}));
  for (let i = 0; i < 4; i++) {
    const a = i * Math.PI / 2 + Math.PI / 4;
    frame.push(M.pipe([Math.cos(a) * 0.5, 0.02, Math.sin(a) * 0.5], [Math.cos(a) * 0.2, 0.12, Math.sin(a) * 0.2], 0.02, 10));
  }
  const coils = [];
  for (let k = 0; k < 4; k++) coils.push(M.T(M.torus(0.2, 0.035, 32, 10), {pos: [0, 0.1 + k * 0.07, 0]}));
  for (let i = 0; i < 6; i++) {
    const a = i * Math.PI / 3;
    coils.push(M.pipe([Math.cos(a) * 0.2, 0.1, Math.sin(a) * 0.2], [Math.cos(a) * 0.2, 0.31, Math.sin(a) * 0.2], 0.012, 8));
  }
  const noz = [M.cyl(0.06, 0.08, 20, 0.33), M.frustum(0.05, 0.03, 0.05, 20, 0.41)];
  const valve = M.merge([M.cyl(0.05, 0.08, 20, 0.12), M.pipe([0.05, 0.16, 0], [0.45, 0.2, 0], 0.025, 12)]);
  const knob = M.T(M.sphere(0.04, 16, 10), {pos: [0.47, 0.2, 0]});
  const blue = M.frustum(0.04, 0.025, 0.06, 20, 0.46);
  const flame = M.frustum(0.035, 0.0, 0.13, 20, 0.47);
  return [
    {material: "dark_steel", look: "solid", mesh: M.merge(frame)},
    {material: "steel", look: "solid", mesh: M.merge(coils.concat(noz))},
    {material: "dark_steel", look: "solid", mesh: M.merge([valve, knob])},
    {material: "blue", look: "glow", mesh: blue},
    {material: "flame", look: "glow", mesh: flame}
  ];
}

function build(M) {
  const prof = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const y = t * 7;
    let r;
    if (t < 0.25) r = 0.5 + (t / 0.25) * 1.6;
    else {
      const u = (t - 0.25) / 0.75;
      r = 2.1 + 0.9 * Math.sin(u * Math.PI * 0.55) ;
      r = Math.min(r, 3.0) * Math.sqrt(Math.max(0, 1 - Math.pow((u - 0.35) / 0.65, 2))) + 0.0;
      if (u < 0.35) r = 2.1 + 0.9 * Math.sin(u / 0.35 * Math.PI / 2);
    }
    prof.push([Math.max(r, 0.001), y]);
  }
  prof[24][0] = 0.001;
  const rAt = y => { for (let i = 1; i < prof.length; i++) if (prof[i][1] >= y) { const a = prof[i - 1], b = prof[i]; return a[0] + (b[0] - a[0]) * (y - a[1]) / (b[1] - a[1]); } return 0; };
  const N = 12, seg = 4;
  const groups = { red: [], gold: [], blue: [] };
  const mats = ["red", "gold", "blue"];
  for (let k = 0; k < N; k++) {
    const m = M.mesh();
    const a0 = k / N * Math.PI * 2, a1 = (k + 1) / N * Math.PI * 2;
    for (let i = 0; i < prof.length - 1; i++) {
      const [r0, y0] = prof[i], [r1, y1] = prof[i + 1];
      for (let j = 0; j < seg; j++) {
        const b0 = a0 + (a1 - a0) * j / seg, b1 = a0 + (a1 - a0) * (j + 1) / seg;
        const P = (r, y, a) => M.vert(m, [r * Math.cos(a), y - 3.5, -r * Math.sin(a)], [Math.cos(a), 0.2, -Math.sin(a)]);
        const p0 = P(r0, y0, b0), p1 = P(r0, y0, b1), p2 = P(r1, y1, b1), p3 = P(r1, y1, b0);
        m.i.push(p0, p1, p2, p0, p2, p3);
      }
    }
    groups[mats[k % 3]].push(m);
  }
  const tapes = [];
  for (let k = 0; k < N; k++) {
    const a = k / N * Math.PI * 2;
    for (let i = 0; i < prof.length - 2; i++) {
      const [r0, y0] = prof[i], [r1, y1] = prof[i + 1];
      tapes.push(M.pipe([r0 * 1.005 * Math.cos(a), y0 - 3.5, -r0 * 1.005 * Math.sin(a)], [r1 * 1.005 * Math.cos(a), y1 - 3.5, -r1 * 1.005 * Math.sin(a)], 0.025, 6));
    }
  }
  for (const y of [0.05, 1.75, 4.2]) tapes.push(M.T(M.torus(rAt(y) * 1.005, 0.03, 48, 6), { pos: [0, y - 3.5, 0] }));
  const crown = M.T(M.torus(0.6, 0.04, 32, 6), { pos: [0, 6.85 - 3.5 + 0.02, 0] });
  return [
    { material: "red", look: "solid", mesh: M.merge(groups.red) },
    { material: "gold", look: "solid", mesh: M.merge(groups.gold) },
    { material: "blue", look: "solid", mesh: M.merge(groups.blue) },
    { material: "white", look: "solid", mesh: M.merge(tapes.concat([crown])) }
  ];
}

function build(M) {
  const prof = [];
  for (let i = 0; i <= 24; i++) {
    const t = i / 24, a = t * Math.PI;
    const y = -2.75 + t * 5.5;
    let r = Math.sin(a) * 2.5 * (0.55 + 0.45 * t);
    if (t < 0.15) r = Math.max(r, 0.4 + t * 2);
    if (i === 24) r = 0;
    prof.push([r, y]);
  }
  prof.unshift([0, -2.75]);
  const cloud = M.lathe(prof, 40);
  const swirls = [];
  for (let k = 0; k < 3; k++) {
    const pts = [];
    for (let j = 0; j <= 40; j++) {
      const t = j / 40, ang = t * Math.PI * 4 + k * 2.1;
      const y = -2.2 + t * 4.2;
      const rr = (0.4 + 0.9 * Math.sin(t * Math.PI)) * (0.6 + k * 0.15);
      pts.push([Math.cos(ang) * rr, y + 0.15 * Math.sin(ang * 2), Math.sin(ang) * rr]);
    }
    for (let j = 0; j < 40; j++) swirls.push(M.pipe(pts[j], pts[j + 1], 0.04, 8));
  }
  const core = M.T(M.sphere(1.2, 24, 16), {pos: [0, 0.6, 0], s: [1, 1.2, 1]});
  return [
    {material: "orange", look: "glass", mesh: cloud},
    {material: "red", look: "glass", mesh: core},
    {material: "flame", look: "glow", mesh: M.merge(swirls)}
  ];
}

function build(M) {
  const skirt = M.lathe([[0.55,0],[0.6,0.25],[0.72,0.55],[0.9,0.85],[0.95,1.0],[0.92,1.0],[0.87,0.85],[0.69,0.55],[0.57,0.25],[0.52,0]], 40);
  const bottomRim = M.T(M.torus(0.54, 0.035, 40, 10), {pos:[0,0.01,0]});
  const topRim = M.T(M.torus(0.935, 0.03, 40, 10), {pos:[0,0.99,0]});
  const tapes = [];
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI * 2 / 12, c = Math.cos(a), s = Math.sin(a);
    tapes.push(M.pipe([0.56*c,0.02,0.56*s],[0.94*c,0.98,0.94*s],0.018,8));
  }
  const cables = [];
  for (let i = 0; i < 6; i++) {
    const a = i * Math.PI / 3 + 0.26, c = Math.cos(a), s = Math.sin(a);
    cables.push(M.pipe([0.54*c,0.01,0.54*s],[0.48*c,-0.0,0.48*s],0.012,6));
  }
  return [
    {material:"dark_steel", look:"solid", mesh: skirt},
    {material:"steel", look:"solid", mesh: M.merge([bottomRim, ...cables])},
    {material:"orange", look:"solid", mesh: M.merge([topRim, ...tapes])}
  ];
}

function build(M) {
  const cap = M.lathe([[0,0.2],[0.3,0.19],[0.55,0.16],[0.72,0.11],[0.75,0.08],[0.72,0.07],[0.55,0.13],[0.3,0.16],[0,0.17]], 40);
  const rim = M.T(M.torus(0.73, 0.02, 40, 8), {pos:[0,0.085,0]});
  const seams = [];
  for (let i = 0; i < 12; i++) {
    const a = i * Math.PI / 6;
    seams.push(M.pipe([0.05*Math.cos(a),0.205,0.05*Math.sin(a)],[0.72*Math.cos(a),0.115,0.72*Math.sin(a)],0.008,6));
  }
  const cords = [];
  for (let i = 0; i < 16; i++) {
    const a = i * Math.PI / 8;
    cords.push(M.pipe([0.72*Math.cos(a),0.08,0.72*Math.sin(a)],[0.25*Math.cos(a),-0.08,0.25*Math.sin(a)],0.006,5));
  }
  const ring = M.T(M.torus(0.25, 0.015, 32, 8), {pos:[0,-0.08,0]});
  const line = M.pipe([0,-0.08,0],[0,-0.1,0],0.01,6);
  const hub = M.cyl(0.05, 0.015, 24, 0.195);
  return [
    {material:"white", look:"solid", mesh: cap},
    {material:"red", look:"solid", mesh: M.merge([rim, ...seams, hub])},
    {material:"dark_steel", look:"solid", mesh: M.merge([...cords, ring, line])}
  ];
}
